#pragma once
#include "ksEditDecisionTask.h"
#include "ksEditAddressTask.h"
#include "ksStateNameEditorTask.h"
#include "ksStateNameCodecTask.h"
#include "ksStateSceneService.h"
#include <array>
#include <optional>
#include <variant>
#include <stdexcept>
namespace ks {
// Connected scene navigation, value editing and name policy. Outgoing children
// are typed semantic requests serviced by the owning native Field graph.
class StateSceneEditCoordinator final {
public:
 enum class Kind {Increment,Decrement,Sub,Adjust,Record,Field,Clamp,ClearSuffix,MoveName,InsertSpace,AdjustName,CommitName,ReadName,DecodeName,EncodeName};
 enum class Component {Decision,Address,Name,Codec};
 enum class Request {None,SceneApply,SceneSelectBank,SceneMap,UiRefresh,Character};
 struct Input {uint16_t event=0;uint8_t character=0;uint32_t nameTarget=0;};
 struct RequestInput {uint16_t character=0,event=0;uint8_t selectedBank=0;bool savePrevious=false;};
 struct Effect {bool read=false,write=false;};
 static constexpr unsigned NoNode=~0u;
 struct Facts {uint32_t base=0,target=0,limit=0,preview=0;uint16_t row=0;uint8_t mode=0,originalRow=0,originalField=0,originalBank=0,previousIndex=0,value=0,maximum=0,lastByte=0,bank=0,cursor=0,index=0,character=0,caseValue=0,decodeInput=0;bool valueObserved=false,limitObserved=false,caseObserved=false,readObserved=false,scene=false,ui=false,display=false;};
 struct Outcome {Kind kind=Kind::Record;Input input{};Facts facts{};EditAddressTask address{EditAddressTask::Kind::Record};std::array<unsigned,5>children{{NoNode,NoNode,NoNode,NoNode,NoNode}};unsigned childCount=0;};
 struct Summary {std::array<Outcome,16>calls{};unsigned count=0;uint16_t presentation=0;bool sceneObserved=false,uiObserved=false,displayObserved=false;};
 explicit StateSceneEditCoordinator(Kind k):StateSceneEditCoordinator(k,Input{}){}
 StateSceneEditCoordinator(Kind k,Input in):kind_(k),input_(in){summary_.presentation=in.event;push(k,in);}
 Kind kind()const{return kind_;}Component component()const{return component_;}uint32_t components()const{return components_;}unsigned depth()const{return depth_;}bool complete()const{return !depth_&&request_==Request::None;}Request request()const{return request_;}const Effect&effect()const{return effect_;}const Summary&summary()const{return summary_;}RequestInput requestInput()const{return requestInput_;}
 template<class T>const T*task()const{return depth_?std::get_if<T>(&frames_[depth_-1]->task):nullptr;}
 bool resumeScene(uint16_t presentation){if(request_!=Request::SceneApply&&request_!=Request::SceneMap&&request_!=Request::SceneSelectBank)return false;const bool tail=request_==Request::SceneSelectBank;request_=Request::None;summary_.presentation=presentation;summary_.sceneObserved=true;if(tail){finish();return true;}auto&t=std::get<EditDecisionTask>(frames_[depth_-1]->task);if(!t.resumeChild())throw std::logic_error("Invalid edit scene completion");return true;}
 bool resumeUi(uint16_t presentation){if(request_!=Request::UiRefresh)return false;request_=Request::None;summary_.presentation=presentation;summary_.uiObserved=true;if(auto*t=std::get_if<StateNameEditorTask>(&frames_[depth_-1]->task)){if(!t->retireTail())throw std::logic_error("Invalid edit UI completion");}finish();return true;}
 bool resumeCharacter(uint16_t presentation){if(request_!=Request::Character)return false;request_=Request::None;summary_.presentation=presentation;summary_.displayObserved=true;auto&t=std::get<StateNameEditorTask>(frames_[depth_-1]->task);if(!t.resumeChild())throw std::logic_error("Invalid edit LCD completion");return true;}
 template<class Peek>static bool admitted(Kind kind,const Input&in,Peek&&peek){
  if(kind==Kind::CommitName&&!StateSceneCoordinator::dataSpan(in.nameTarget,1))return false;
  const bool record=kind==Kind::Record||kind==Kind::Field||(kind==Kind::Adjust&&uint8_t(peek(0x1679f))==0&&uint8_t(peek(0x17492))!=0);
  if(!record)return true;uint32_t base=0;for(unsigned n=0;n<4;++n)base=(base<<8)|uint8_t(peek(0x1748e + n));const auto row=unsigned(uint8_t(uint8_t(peek(0x17492))-1))*8;const auto target=base+row+16;if(!StateSceneCoordinator::dataSpan(target,2))return false;
  if(kind!=Kind::Record){const auto offset=uint8_t(uint8_t(peek(0x17493))*2);if(!StateSceneCoordinator::dataSpan(target+offset+1,1)||!StateSceneCoordinator::dataSpan(0x1510d + row+offset+1,1))return false;}return true;
 }
 unsigned nextClocks(int previous=-1)const{if(!depth_||request_!=Request::None)return 0;const auto&f=*frames_[depth_-1];return std::visit([&](const auto&t)->unsigned{using T=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<T,EditDecisionTask>)return t.nextClocks(decisionCost(t,previous));else if constexpr(std::is_same_v<T,EditAddressTask>)return t.nextClocks(t.stage()==T::Stage::RecordReadBase?6:3);else if constexpr(std::is_same_v<T,StateNameEditorTask>)return t.nextClocks(nameCost(f,t,previous));else return t.nextClocks(codecCost(t,previous));},f.task);}
 template<class R,class W>unsigned advanceBefore(unsigned available,R&&read,W&&write,int previous=-1){const auto cost=nextClocks(previous);if(!cost||cost>available)return 0;effect_={};auto&f=*frames_[depth_-1];auto&o=summary_.calls[f.node];
 auto byte=[&](uint32_t a,unsigned back=0){if(!StateSceneCoordinator::dataSpan(a,1))throw std::logic_error("Unsupported evolving scene edit read");return uint8_t(read(a&0xffffff,cost-back));};auto put=[&](uint32_t a,uint8_t v){if(!StateSceneCoordinator::dataSpan(a,1))throw std::logic_error("Unsupported evolving scene edit write");write(a&0xffffff,v,cost);};
 std::visit([&](auto&t){using T=std::decay_t<decltype(t)>;
 if constexpr(std::is_same_v<T,EditDecisionTask>){using S=typename T::Stage;const auto stage=t.stage();t.advanceBefore(cost,[&](S s)->uint32_t{switch(s){case S::IncrementReadMode:case S::DecrementReadMode:case S::SubReadMode:case S::AdjustReadMode:return o.facts.mode=byte(0x1679f);case S::IncrementReadRow:case S::DecrementReadRow:case S::AdjustReadRow:return o.facts.originalRow=byte(0x17492);case S::SubReadField:return o.facts.originalField=byte(0x17493);case S::AdjustReadPreview:return o.facts.lastByte=byte(t.preview()+t.index(),2);case S::AdjustReadValue:o.facts.valueObserved=true;return o.facts.value=byte(t.field());case S::AdjustReadLimit:o.facts.limitObserved=true;return o.facts.maximum=byte(t.limit());default:throw std::logic_error("Unsupported edit decision read");}},[&](S s,uint32_t v){switch(s){case S::IncrementPublishRow:case S::DecrementPublishRow:put(0x17492,uint8_t(v));break;case S::SubPublish:put(0x17493,uint8_t(v));break;case S::AdjustPublishBank:put(0x1679e,uint8_t(v));break;case S::AdjustPublishPreview:put(0x1733c + t.index(),uint8_t(v));break;case S::AdjustPublishValue:put(t.field(),uint8_t(v));break;default:throw std::logic_error("Unsupported edit decision write");}},[&](S){return decisionCost(t,previous);});o.facts.bank=t.bank();o.facts.preview=t.preview();
  if(stage==S::AdjustSignDelta)summary_.presentation=uint16_t(int16_t(int8_t(f.input.event)));if(t.awaitingChild()){effect_.write=true;using C=typename T::Child;switch(t.child()){case C::Clamp:push(Kind::Clamp,f.input);break;case C::Field:push(Kind::Field,f.input);break;case C::Map:o.facts.scene=true;ask(Request::SceneMap,{summary_.presentation,summary_.presentation,0,false});break;case C::ApplyScene:o.facts.scene=true;ask(Request::SceneApply,{summary_.presentation,summary_.presentation,0,false});break;default:throw std::logic_error("Unsupported edit decision child");}}
  else if(t.handoff()){using Q=typename T::Route;if(t.route()==Q::Refresh){o.facts.ui=true;ask(Request::UiRefresh,{summary_.presentation,summary_.presentation,0,false});}else if(t.route()==Q::SelectBank){o.facts.scene=true;ask(Request::SceneSelectBank,{summary_.presentation,summary_.presentation,t.bank(),false});}else{const auto k=t.route()==Q::IncrementText?Kind::ClearSuffix:t.route()==Q::DecrementText?Kind::InsertSpace:t.route()==Q::SubText?Kind::MoveName:t.route()==Q::AdjustText?Kind::AdjustName:Kind::Record;if(k==Kind::Record)throw std::logic_error("Unsupported scene edit text tail");f.tailChild=true;auto in=f.input;in.event=summary_.presentation;push(k,in);}}
  else if(t.complete()){effect_.read=true;finish();}
 }else if constexpr(std::is_same_v<T,EditAddressTask>){using S=typename T::Stage;const auto stage=t.stage();t.advanceBefore(cost,[&](S s)->uint32_t{switch(s){case S::RecordRead:return o.facts.originalRow=byte(0x17492);case S::RecordReadBase:{uint32_t v=0;for(unsigned n=0;n<4;++n)v=(v<<8)|byte(0x1748e + n,3*((3-n)/2));if(!StateSceneCoordinator::dataSpan(v+t.row()+16,2))throw std::logic_error("Unsupported evolving edit record base");return o.facts.base=v;}case S::FieldReadSubindex:return o.facts.originalField=byte(0x17493);case S::ClampRead:return o.facts.originalBank=byte(0x1679e);default:throw std::logic_error("Unsupported edit address read");}},[](S,uint32_t){throw std::logic_error("Unexpected edit address publication");},[&](S){return stage==S::RecordReadBase?6:3;});
  if(stage==S::FieldValueByte&&!StateSceneCoordinator::dataSpan(t.record(),1))throw std::logic_error("Unsupported evolving edit field target");if(stage==S::FieldLimitValue&&!StateSceneCoordinator::dataSpan(t.limit(),1))throw std::logic_error("Unsupported evolving edit field limit");
  if(t.awaitingChild()){effect_.write=true;push(Kind::Record,f.input);}else if(t.complete()){o.address=t;o.facts.target=t.record();o.facts.limit=t.limit();o.facts.row=t.row();o.facts.bank=t.bank();effect_.read=true;finish();}
 }else if constexpr(std::is_same_v<T,StateNameEditorTask>){using S=typename T::Stage;const auto stage=t.stage();t.advanceBefore(cost,[&](typename T::Read r)->uint32_t{switch(r){case T::Read::SuffixCursor:case T::Read::MoveCursor:case T::Read::InsertCursor:return o.facts.cursor=byte(0x167d7);case T::Read::PreviousIndex:return o.facts.previousIndex=byte(0x167d9);default:throw std::logic_error("Unsupported scene name read");}},[&](typename T::Write w,uint8_t v){switch(w){case T::Write::Suffix:put(0x1733c + t.cursor()+t.suffixOffset(),v);break;case T::Write::Cursor:put(0x167d7,v);break;case T::Write::Insert:put(0x1733c + t.cursor(),v);break;case T::Write::Index:o.facts.index=v;put(0x167d9,v);break;case T::Write::Name:o.facts.character=v;put(f.nameTarget,v);break;default:throw std::logic_error("Unsupported scene name write");}},nameCost(f,t,previous));
  if(stage==S::SetSpaceInsert)summary_.presentation=uint16_t((summary_.presentation&0xff00)|32);if(stage==S::SetMoveNext)summary_.presentation=uint16_t((summary_.presentation&0xff00)|1);if(stage==S::SetCursorCommand)summary_.presentation=uint16_t((summary_.presentation&0xff00)|0xc1);if(stage==S::AddCursorCommand)summary_.presentation=uint16_t((summary_.presentation&0xff00)|t.cursorCommand());o.facts.target=f.nameTarget;
  if(t.awaitingChild()){effect_.write=true;using C=typename T::Child;auto in=f.input;in.event=summary_.presentation;switch(t.child()){case C::Read:push(Kind::ReadName,in);break;case C::Decode:in.character=f.character;push(Kind::DecodeName,in);break;case C::Encode:push(Kind::EncodeName,in);break;case C::Move:push(Kind::MoveName,in);break;case C::Cursor:o.facts.display=true;ask(Request::Character,{summary_.presentation,summary_.presentation,0,false});break;}}
  else if(t.awaitingTail()){if(t.tail()!=T::Tail::Display)throw std::logic_error("Unsupported scene name tail");o.facts.ui=true;ask(Request::UiRefresh,{summary_.presentation,summary_.presentation,0,false});}else if(t.complete()){effect_.read=true;finish();}
 }else{const auto stage=t.stage();t.advanceBefore(cost,[&](StateNameCodecTask::Read r)->uint32_t{using Q=StateNameCodecTask::Read;switch(r){case Q::Cursor:return o.facts.cursor=byte(0x167d7);case Q::Character:o.facts.readObserved=true;return o.facts.character=byte(0x1733c + t.cursor());case Q::Index:return o.facts.index=byte(0x167d9);case Q::Case:o.facts.caseObserved=true;return o.facts.caseValue=byte(0x167d8);}throw std::logic_error("Unsupported scene codec read");},[&](StateNameCodecTask::Write w,uint8_t v){put(w==StateNameCodecTask::Write::Case?0x167d8:0x167d9,v);},codecCost(t,previous));if(t.complete()){o.facts.target=0x1733c + t.cursor();o.facts.character=t.character();o.facts.index=t.index();effect_.read=true;finish();}(void)stage;}
 },f.task);if(depth_)select();return cost;}
private:
 using Task=std::variant<EditDecisionTask,EditAddressTask,StateNameEditorTask,StateNameCodecTask>;
 struct Frame{template<class T>Frame(T t,Input i,unsigned n):task(std::move(t)),input(i),node(n),nameTarget(i.nameTarget){}Task task;Input input;unsigned node;uint32_t nameTarget=0;uint8_t character=0;bool tailChild=false;};
 void ask(Request r,RequestInput i){request_=r;requestInput_=i;}
 void push(Kind k,Input i){if(depth_==frames_.size()||summary_.count==summary_.calls.size())throw std::logic_error("Scene edit capacity");const auto n=summary_.count++;auto&o=summary_.calls[n];o.kind=k;o.input=i;o.facts.decodeInput=i.character;if(depth_){auto&p=summary_.calls[frames_[depth_-1]->node];if(p.childCount==p.children.size())throw std::logic_error("Scene edit child capacity");p.children[p.childCount++]=n;}if(k<=Kind::Adjust)frames_[depth_++].emplace(EditDecisionTask(EditDecisionTask::Kind(unsigned(k)+unsigned(EditDecisionTask::Kind::Increment)),uint8_t(i.event>>8),uint8_t(i.event)),i,n);else if(k<=Kind::Clamp)frames_[depth_++].emplace(EditAddressTask(k==Kind::Record?EditAddressTask::Kind::Record:k==Kind::Field?EditAddressTask::Kind::Field:EditAddressTask::Kind::Clamp,uint8_t(i.event)),i,n);else if(k<=Kind::CommitName){using N=StateNameEditorTask;const auto nk=k==Kind::ClearSuffix?N::Kind::ClearSuffix:k==Kind::MoveName?N::Kind::Move:k==Kind::InsertSpace?N::Kind::InsertSpace:k==Kind::AdjustName?N::Kind::Adjust:N::Kind::Commit;frames_[depth_++].emplace(N(nk,uint8_t(i.event)),i,n);}else frames_[depth_++].emplace(StateNameCodecTask(k==Kind::ReadName?StateNameCodecTask::Kind::Read:k==Kind::DecodeName?StateNameCodecTask::Kind::Decode:StateNameCodecTask::Kind::Encode,i.character),i,n);select();}
 void finish(){const auto result=summary_.calls[frames_[depth_-1]->node];frames_[--depth_].reset();if(!depth_)return;auto&f=*frames_[depth_-1];if(f.tailChild){finish();return;}std::visit([&](auto&t){using T=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<T,EditDecisionTask>){if(result.kind==Kind::Clamp)t.resumeBank(result.address.bank());else if(result.kind==Kind::Field)t.resumeField(result.address.record(),result.address.limit());else throw std::logic_error("Invalid scene edit address child");}else if constexpr(std::is_same_v<T,EditAddressTask>)t.resumeRecord(result.address.record(),result.address.row());else if constexpr(std::is_same_v<T,StateNameEditorTask>){if(result.kind==Kind::ReadName){f.nameTarget=result.facts.target;f.character=result.facts.character;}if(result.kind==Kind::EncodeName)f.character=result.facts.character;if(result.kind==Kind::DecodeName)t.resumeChild(result.facts.index);else t.resumeChild(f.character);}},f.task);select();}
 void select(){component_=std::visit([](const auto&t){using T=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<T,EditDecisionTask>)return Component::Decision;else if constexpr(std::is_same_v<T,EditAddressTask>)return Component::Address;else if constexpr(std::is_same_v<T,StateNameEditorTask>)return Component::Name;else return Component::Codec;},frames_[depth_-1]->task);components_|=1u<<unsigned(component_);}
 static unsigned byteClock(uint32_t raw,int p){const auto a=raw&0xffffff;return a<0x400000&&!(p&1)&&a==(uint32_t(p)|1u)?0:3;}
 static unsigned decisionCost(const EditDecisionTask&t,int p){using S=EditDecisionTask::Stage;switch(t.stage()){case S::IncrementPublishRow:case S::DecrementPublishRow:return byteClock(0x17492,p);case S::SubPublish:return byteClock(0x17493,p);case S::AdjustPublishBank:return byteClock(0x1679e,p);case S::AdjustPublishPreview:return byteClock(0x1733c + t.index(),p);case S::AdjustPublishValue:return byteClock(t.field(),p);default:return 3;}}
 static unsigned nameCost(const Frame&f,const StateNameEditorTask&t,int p){using S=StateNameEditorTask::Stage;switch(t.stage()){case S::WriteSpace:return byteClock(0x1733c + t.cursor()+t.suffixOffset(),p);case S::WriteMoveCursor:return byteClock(0x167d7,p);case S::WriteInsert:return byteClock(0x1733c + t.cursor(),p);case S::WriteIndex:return byteClock(0x167d9,p);case S::WriteName:return byteClock(f.nameTarget,p);default:return 3;}}
 static unsigned codecCost(const StateNameCodecTask&t,int p){return byteClock(t.stage()==StateNameCodecTask::Stage::WriteCase?0x167d8:0x167d9,p);}
 Kind kind_;Input input_;std::array<std::optional<Frame>,5>frames_{};unsigned depth_=0;Request request_=Request::None;RequestInput requestInput_{};Component component_=Component::Decision;uint32_t components_=0;Effect effect_{};Summary summary_{};
};}
